import{z as B,x as l,o as A,c as i,q as t,j as r,D as E,d as s,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"间隔层刻蚀与 SADP","description":"","frontmatter":{"title":"间隔层刻蚀与 SADP","date":"2026-09-27T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/spacer-etch-sadp.md","filePath":"litho/spacer-etch-sadp.md","lastUpdated":1791063341000}'),D={name:"litho/spacer-etch-sadp.md"};function p(d,a,m,c,h,S){const e=l("Mermaid");return A(),i("div",null,[a[2]||(a[2]=t('<h1 id="间隔层刻蚀与-sadp" tabindex="-1">间隔层刻蚀与 SADP <a class="header-anchor" href="#间隔层刻蚀与-sadp" aria-label="Permalink to &quot;间隔层刻蚀与 SADP&quot;">​</a></h1><div class="epigraph"><p>SADP 不靠镜头画第二条线，靠第一层图形当模具：沉积一层、刻一个方向，间隔层自己长出半节距的墙。</p><footer>—— 据 ASML/TEL SADP 工艺文献；NEC/东芝 32nm 闪存量产记录</footer></div><p><a href="/litho/post-hyper-na-limits">后 Hyper-NA 的极限讨论</a>把「光刻分辨率到头了」摆在桌面，本课是图形化的第一条出路：<strong>自对准双重图形化（SADP）</strong>——用光刻画一次粗线，靠薄膜沉积与定向刻蚀长出间隔层，把节距折半。它是 20nm 之后闪存与逻辑的量产主力。本课不做 LE3/LE4 的推广计数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>193i 浸没式单次曝光的分辨率极限约 38–40nm 半节距，而 NAND 要 15nm 以下。双重曝光（LELE 两次光刻）受套刻精度折磨——两条线各自的位置误差直接相加。缺口：<strong>自对准</strong>——第二条线不是「画」出来的，是从第一条线的侧壁「长」出来的，位置由薄膜厚度决定，精度是埃米级而非套刻级。</p><p><span class="marginnote">术语翻译：间隔层（spacer）= 沿芯轴侧壁各向异性沉积出的薄膜墙，厚度 = 目标半节距；芯轴（mandrel/芯轴）= 被刻蚀掉的临时图形；block（阻断层）= 切断不需要的间隔层的第二层光刻。</span></p><p><span class="marginnote">数字实例：目标 30nm 节距。光刻画 60nm 芯轴 → 沉积 15nm 氮化硅间隔层（两侧各 15）→ 刻掉芯轴 → 剩两条间隔层，中心距 60-15-15=30nm。节距由膜厚决定，膜厚控制 ±0.5nm 级——比任何套刻都准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SADP 流五步：光刻芯轴并刻蚀；各向异性沉积间隔层（ALD 保均匀）；间隔层开口（刻穿顶部、留住侧壁）；选择性刻掉芯轴；以间隔层为硬掩模转移图形到目标层。若需要的是「线」的补集（沟槽 vs 线条），间隔层本身就是答案——芯轴定义线，间隔层定义槽，两次使用各取所需。需要 cut/block 时再叠一层光刻，套刻要求只作用在「切断」而非「定位」。</p>',9)),(A(),r(o,null,{default:E(()=>[n(e,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%85%89%E5%88%BB%E8%8A%AF%E8%BD%B4%20%2B%20%E5%88%BB%E8%9A%80%22%5D%20--%3E%20B%5B%22ALD%20%E6%B2%89%E7%A7%AF%E9%97%B4%E9%9A%94%E5%B1%82%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%90%84%E5%90%91%E5%BC%82%E6%80%A7%E5%BC%80%E5%8F%A3%22%5D%0A%20%20C%20--%3E%20D%5B%22%E9%80%89%E6%8B%A9%E6%80%A7%E5%8E%BB%E6%8E%89%E8%8A%AF%E8%BD%B4%22%5D%0A%20%20D%20--%3E%20E%5B%22%E9%97%B4%E9%9A%94%E5%B1%82%20%3D%20%E6%96%B0%E7%A1%AC%E6%8E%A9%E6%A8%A1%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%9B%BE%E5%BD%A2%E8%BD%AC%E7%A7%BB%E8%87%B3%E7%9B%AE%E6%A0%87%E5%B1%82%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">直觉类比：像用蜡笔在墙上画粗道子，再沿道子两边贴胶带、撕掉蜡笔——两条胶带的位置由「道宽 + 胶带厚」决定，不由手抖决定；胶带厚度是纳米级可控的，手抖不是。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自对准的本质是<strong>把定位问题转化为膜厚问题</strong>。套刻误差是光刻机与晶圆的系统性错位（几十纳米级、需昂贵的对准开销），而间隔层厚度由 ALD 的每周期生长量（约 0.1nm/周期）决定，晶圆内均匀性 &lt;1%。代价在三处：<strong>线宽由芯轴与膜厚共同决定</strong>——芯轴 CD 波动直接传导；<strong>LWR（线宽粗糙度）叠加</strong>——芯轴边缘粗糙度与间隔层粗糙度串联恶化；<strong>block 层回归</strong>——切断间隔层的光刻承担了全部随机图形，其套刻误差决定良率上限，这也是 SADP 时代 overlay 计量被推到 &lt;2nm 的原因。</p>',3)),(A(),r(o,null,{default:E(()=>[n(e,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E8%8A%82%E8%B7%9D%E4%B8%BA%E4%BD%95%E5%87%8F%E5%8D%8A%3F%22%7D%20--%3E%20R%5B%22%E5%AE%9A%E4%BD%8D%20%3D%20%E8%86%9C%E5%8E%9A%E9%97%AE%E9%A2%98%22%5D%0A%20%20R%20--%3E%20S%5B%22ALD%20%E5%9F%83%E7%B1%B3%E7%BA%A7%E6%8E%A7%E5%88%B6%22%5D%0A%20%20T%7B%22%E4%BB%A3%E4%BB%B7%E5%9C%A8%E5%93%AA%3F%22%7D%20--%3E%20U%5B%22%E8%8A%AF%E8%BD%B4%20CD%20%E6%B3%A2%E5%8A%A8%E4%BC%A0%E5%AF%BC%E7%BA%BF%E5%AE%BD%22%5D%0A%20%20T%20--%3E%20V%5B%22%E7%B2%97%E7%B3%99%E5%BA%A6%E4%B8%B2%E8%81%94%20LWR%20%E6%81%B6%E5%8C%96%22%5D%0A%20%20T%20--%3E%20W%5B%22block%20%E5%B1%82%E6%89%BF%E6%8B%85%E5%A5%97%E5%88%BB%E5%8E%8B%E5%8A%9B%22%5D%0A%20%20U%20--%3E%20X%5B%22%E8%89%AF%E7%8E%87%E4%B8%89%E8%A7%92%3A%20%E8%8A%82%E8%B7%9D%2F%E7%BA%BF%E5%AE%BD%2F%E7%BC%BA%E9%99%B7%22%5D%0A%20%20V%20--%3E%20X%0A%20%20W%20--%3E%20X%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">常见误区：把 SADP 与 LELE 混为一谈——LELE 两条线两次光刻、误差相加，SADP 一条线长两条、误差是膜厚级；另一误区是「间隔层越薄越好」——膜厚即半节距，膜厚崩塌意味着节距崩塌，SADP 的分辨率红利与膜厚工艺窗口是同一枚硬币。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>SADP 只能做<strong>周期性图形</strong>：随机逻辑的 cut/block 密度高时收益被 block 层套刻吃掉，故 SRAM/闪存先吃红利、逻辑后跟进。EUV 时代 SADP 的角色变化：EUV 单次即可 30nm 节距，SADP 从「分辨率救星」转为「节距倍增 + 缺陷兜底」的选择。SAQP（四重图形化）把间隔层做两轮，节距再折半，但缺陷叠加让良率管理成为核心工艺。与<a href="/litho/dummy-fill-density">虚拟填充与密度规则</a>的接续：SADP 对图形规律性的要求，正是密度规则必须Preserve 的前提——图形化与填充是一对约束。</p><p><span class="marginnote">直觉类比：SADP 像「描红」——不用再手写第二个字（二次光刻），把第一个字的笔画轮廓描一圈（间隔层），字与字的间距由描边厚度决定；描边均匀（ALD）比再写一次（套刻）工整得多。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SADP = 芯轴光刻 + 间隔层沉积，节距折半且定位转膜厚问题。</li><li>芯轴 CD 与粗糙度传导、block 层套刻是三大代价。</li><li>周期性图形的主场；SAQP 再折半、EUV 时代转型为节距倍增器。</li><li>出处：ASML SADP 技术白皮书；TEL 间隔层工艺文献；IEEE IITC SADP 缺陷研究。</li></ul>',6))])}const T=B(D,[["render",p]]);export{P as __pageData,T as default};
